// defines pins numbers
const int trigPin = 12;
const int echoPin = 13;

// defines variables
long duration;
int distance;

void setup() 
{
  Serial.begin(9600);
    pinMode(trigPin, OUTPUT); // Sets the trigPin as an Output
      pinMode(echoPin, INPUT); // Sets the echoPin as an Input
        pinMode(2, INPUT); // Sets the IR as an Input
          pinMode(11, OUTPUT); // Sets the Pin as an Output
          }
          void loop() 
          {
            int IR = digitalRead(2);

                if(IR == HIGH)
                  {
                      Serial.print("Glass Avaiable   ");
                          // Clears the trigPin
                            digitalWrite(trigPin, LOW);
                              delayMicroseconds(2);

                                // Sets the trigPin on HIGH state for 10 micro seconds
                                  digitalWrite(trigPin, HIGH);
                                    delayMicroseconds(10);
                                      digitalWrite(trigPin, LOW);

                                        // Reads the echoPin, returns the sound wave travel time in microseconds
                                          duration = pulseIn(echoPin, HIGH);

                                            // Calculating the distance in cm
                                              distance = duration*0.034/2;

                                                  int D = map(distance, 10, 1095, 0, 400); 

                                                      if(D < 200)
                                                        {
                                                            Serial.println("Pump: Start");
                                                                digitalWrite(11,HIGH);
                                                                  }
                                                                    else
                                                                      {
                                                                          Serial.println("Glass: Full ");
                                                                              digitalWrite(11,LOW);
                                                                                }
                                                                                 }
                                                                                  else
                                                                                    {
                                                                                        Serial.println("No Glass ");
                                                                                            digitalWrite(11,LOW);
                                                                                              }
                                                                                              }
